def link(slug): return slug + '.html'
def put(root, slug, title, description, content):
    (root / 'src/pages' / (slug+'.html')).write_text(content,encoding='utf-8')
    META[slug]=(title+' | OrbitIT Solution Limited',description)

def intro(title, description, eyebrow='ORBITIT SOLUTION LIMITED', crumb=''):
    return f'<section class="page-intro"><div class="container"><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span>{e(crumb or title)}</div><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="intro-text">{description}</p></div><div class="intro-orbit" aria-hidden="true"></div></section>'

def cta():
    return '<section class="section"><div class="container"><div class="cta-block"><div><p class="eyebrow">YOUR NEXT MOVE</p><h2>Good ideas deserve<br>a clear direction.</h2><p>Let’s turn what you have in mind into an agreed plan.</p></div><a class="btn btn-lime" href="contact.html">Tell us about your project <span aria-hidden="true">↗</span></a></div></div></section>'

def service_card(s, i):
    return f'<div class="col-md-6 col-lg-4" data-category="{s["group"]}"><a class="service-card" href="{link(s["slug"])}"><div class="card-top"><span class="icon-box" aria-hidden="true">{e(s["icon"])}</span><span class="card-num">{i:02d}</span></div><h3>{e(s["name"])}</h3><p>{e(s["line"])}</p><span class="card-action">Explore service <span aria-hidden="true">↗</span></span></a></div>'

def package_card(p, featured=False):
    return f'''<div class="col-md-6 col-lg-4" data-category="{p['category']}"><article class="price-card{' featured' if featured else ''}" id="{p['id']}"><div class="price-category">{p['category']} <span>FIXED SCOPE</span></div><h3>{e(p['name'])}</h3><div class="price"><span>£</span>{p['price']}<small>GBP / {p['unit']}</small></div><p>{e(p['detail'])}</p><ul class="check-list">{''.join('<li>'+e(x)+'</li>' for x in p['includes'])}</ul><p class="price-exclusion"><strong>Not included:</strong> {e(p['excludes'])}</p><a class="btn {'btn-lime' if featured else 'btn-outline'} w-100" href="contact.html?package={p['id']}">Discuss this package <span aria-hidden="true">↗</span></a></article></div>'''

def team_cards(limit=None):
    return ''.join(f'<div class="col-sm-6 col-lg-3"><article class="team-card"><div class="portrait"><img src="assets/images/team-member/{photo}" alt="{name}, {role}" width="500" height="600" loading="lazy"></div><div class="team-info"><span>{role}</span><h3>{name}</h3><a href="mailto:{email}@orbitits.com">{email}@orbitits.com <span aria-hidden="true">↗</span></a></div></article></div>' for name,role,email,photo in TEAM[:limit])

